use serde::{Deserialize, Serialize};
use serde_json::Value;

/// One JSON-RPC request from the injected provider to the host.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProviderRequest {
    /// Correlation id generated by the injected provider.
    pub id: String,
    /// EIP-1193 method name (or an AIOS `wallet_*` method).
    pub method: String,
    /// Positional arguments supplied by the page.
    #[serde(default)]
    pub params: Vec<Value>,
    /// `location.origin` of the calling page, used by the permission policy.
    #[serde(default)]
    pub origin: String,
    /// Set by the provider when running inside the embedded Boa browser.
    #[serde(default)]
    pub embedded: bool,
}

/// Host answer for a provider request.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProviderReply {
    /// Correlation id copied from the request.
    pub id: String,
    /// Successful result, if any.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub result: Option<Value>,
    /// EIP-1193 shaped error, if any.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<ProviderError>,
}

impl ProviderReply {
    /// Build a successful reply.
    pub fn ok(id: String, result: Value) -> Self {
        Self {
            id,
            result: Some(result),
            error: None,
        }
    }

    /// Build an error reply with an EIP-1193 numeric code.
    pub fn err(id: String, code: i64, message: impl Into<String>) -> Self {
        Self {
            id,
            result: None,
            error: Some(ProviderError {
                code,
                message: message.into(),
            }),
        }
    }
}

/// EIP-1193 error object.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProviderError {
    /// Numeric EIP-1193 error code.
    pub code: i64,
    /// Human-readable description.
    pub message: String,
}

/// Built-in network description exposed through `wallet_getChains`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChainInfo {
    /// Hex chain id (e.g. `0x1`).
    pub chain_id: String,
    /// Human-readable network name.
    pub name: String,
    /// Authenticated JSON-RPC endpoint used by the host.
    pub rpc_url: String,
    /// Block explorer base URL (informational).
    pub explorer: String,
    /// Native currency symbol.
    pub symbol: String,
}
